import React, { useEffect, useRef, useState } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { MoreHorizontal, Book, Star, Folder as FolderIcon } from 'react-feather'

import { TestID } from '@resources/TestID'
import { Folder, Shortcuts, ContextMenuEnum } from '@/utils/enums'
import { NoteListButton } from '@/components/NoteList/NoteListButton'
import { SearchBar } from '@/components/NoteList/SearchBar'
import { ContextMenu } from '@/containers/ContextMenu'
import { getNoteTitle, shouldOpenContextMenu, debounceEvent, isDraftNote } from '@/utils/helpers'
import { useKey } from '@/utils/hooks'
import {
  permanentlyEmptyTrash,
  pruneNotes,
  updateActiveNote,
  searchNotes,
  updateSelectedNotes,
} from '@/slices/note'
import { NoteItem, ReactDragEvent, ReactMouseEvent } from '@/types'
import { getNotes, getSettings, getCategories } from '@/selectors'
import { getNotesSorter } from '@/utils/notesSortStrategies'

export const NoteList: React.FC = () => {
  // ===========================================================================
  // Selectors
  // ===========================================================================

  const { notesSortKey } = useSelector(getSettings)
  const { activeCategoryId, activeFolder, selectedNotesIds, notes, searchValue } =
    useSelector(getNotes)
  const { categories } = useSelector(getCategories)

  // ===========================================================================
  // Dispatch
  // ===========================================================================

  const dispatch = useDispatch()

  const _updateSelectedNotes = (noteId: string, multiSelect: boolean) =>
    dispatch(updateSelectedNotes({ noteId, multiSelect }))
  const _permanentlyEmptyTrash = () => dispatch(permanentlyEmptyTrash())
  const _pruneNotes = () => dispatch(pruneNotes())
  const _updateActiveNote = (noteId: string, multiSelect: boolean) =>
    dispatch(updateActiveNote({ noteId, multiSelect }))
  const _searchNotes = debounceEvent(
    (searchValue: string) => dispatch(searchNotes(searchValue)),
    100
  )

  // ===========================================================================
  // Refs
  // ===========================================================================

  const contextMenuRef = useRef<HTMLDivElement>(null)
  const searchRef = React.useRef() as React.MutableRefObject<HTMLInputElement>

  // ===========================================================================
  // State
  // ===========================================================================

  const [optionsId, setOptionsId] = useState('')
  const [optionsPosition, setOptionsPosition] = useState({ x: 0, y: 0 })

  const re = new RegExp(searchValue.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i')
  const isMatch = (result: NoteItem) => re.test(result.text)

  const filter: Record<Folder, (note: NoteItem) => boolean> = {
    [Folder.CATEGORY]: (note) => !note.trash && note.category === activeCategoryId,
    [Folder.SCRATCHPAD]: (note) => !!note.scratchpad,
    [Folder.FAVORITES]: (note) => !note.trash && !!note.favorite,
    [Folder.TRASH]: (note) => !!note.trash,
    [Folder.ALL]: (note) => !note.trash && !note.scratchpad,
  }

  const filteredNotes: NoteItem[] = notes
    .filter(filter[activeFolder])
    .filter(isMatch)
    .sort(getNotesSorter(notesSortKey))

  // ===========================================================================
  // Handlers
  // ===========================================================================

  const focusSearchHandler = () => searchRef.current.focus()

  const handleDragStart = (event: ReactDragEvent, noteId: string = '') => {
    event.stopPropagation()

    event.dataTransfer.setData('text/plain', noteId)
  }

  const handleNoteOptionsClick = (event: ReactMouseEvent, noteId: string = '') => {
    const clicked = event.target

    // Make sure we aren't getting any null values. Any element clicked should be a sub-class of element
    if (!clicked) return

    // Ensure the clicked target is supposed to open the context menu
    if (shouldOpenContextMenu(clicked as Element)) {
      // note: don't check for MouseEvent because Cypress MouseEvent !== Window.MouseEvent
      if ('pageX' in event && 'pageY' in event) {
        setOptionsPosition({ x: event.pageX, y: event.pageY })
      }
    }

    event.stopPropagation()

    if (!contextMenuRef.current || !contextMenuRef.current.contains(clicked as HTMLDivElement)) {
      setOptionsId(!optionsId || optionsId !== noteId ? noteId : '')
    }
  }

  const handleNoteRightClick = (
    event: React.MouseEvent<HTMLDivElement, MouseEvent>,
    noteId: string = ''
  ) => {
    event.preventDefault()
    const clicked = event.target
    const RIGHT_CLICK = 2

    // Make sure we aren't getting any null values .. any element clicked should be a sub-class of element
    if (!clicked) return

    // FIXME: This feels hacky
    if (event.ctrlKey) return

    // Make sure we are not right clicking on the menu
    if (optionsId && event.button == RIGHT_CLICK) return

    if ('clientX' in event && 'clientY' in event) {
      setOptionsPosition({ x: event.clientX, y: event.clientY })
    }

    event.stopPropagation()

    if (!contextMenuRef.current || contextMenuRef.current.contains(clicked as HTMLDivElement)) {
      setOptionsId(!optionsId || optionsId !== noteId ? noteId : '')
    }
  }

  const showEmptyTrash = activeFolder === Folder.TRASH && filteredNotes.length > 0

  // ===========================================================================
  // Hooks
  // ===========================================================================

  useEffect(() => {
    document.addEventListener('mousedown', handleNoteOptionsClick)

    return () => {
      document.removeEventListener('mousedown', handleNoteOptionsClick)
    }
  })

  useKey(Shortcuts.SEARCH, () => focusSearchHandler())

  return (
    <aside className="note-sidebar">
      <div className="note-sidebar-header">
        <SearchBar searchRef={searchRef} searchNotes={_searchNotes} />
        {showEmptyTrash && (
          <NoteListButton
            dataTestID={TestID.EMPTY_TRASH_BUTTON}
            label="Empty"
            handler={() => _permanentlyEmptyTrash()}
          >
            Empty Trash
          </NoteListButton>
        )}
      </div>
      <div data-testid={TestID.NOTE_LIST} className="note-list">
        {filteredNotes.map((note: NoteItem, index: number) => {
          let noteTitle: string | React.ReactElement = getNoteTitle(note.text)
          const noteCategory = categories.find((category) => category.id === note.category)

          if (searchValue) {
            const highlightStart = noteTitle.search(re)

            if (highlightStart !== -1) {
              const highlightEnd = highlightStart + searchValue.length

              noteTitle = (
                <>
                  {noteTitle.slice(0, highlightStart)}
                  <strong className="highlighted">
                    {noteTitle.slice(highlightStart, highlightEnd)}
                  </strong>
                  {noteTitle.slice(highlightEnd)}
                </>
              )
            }
          }

          return (
            <div
              data-testid={TestID.NOTE_LIST_ITEM + index}
              className={
                selectedNotesIds.includes(note.id) ? 'note-list-each selected' : 'note-list-each'
              }
              key={note.id}
              onClick={(event) => {
                event.stopPropagation()

                _updateSelectedNotes(note.id, event.metaKey)
                _updateActiveNote(note.id, event.metaKey)
                _pruneNotes()
              }}
              onContextMenu={(event) => handleNoteRightClick(event, note.id)}
              draggable={note.text !== ''}
              onDragStart={(event) => handleDragStart(event, note.id)}
            >
              <div className="note-list-outer">
                <div data-testid={'note-title-' + index} className="note-title">
                  {note.favorite ? (
                    <>
                      <div className="icon">
                        <Star aria-hidden="true" className="note-favorite" size={12} />
                        <span className="sr-only">Favorite note</span>
                      </div>
                      <div className="truncate-text">{noteTitle}</div>
                    </>
                  ) : (
                    <>
                      <div className="icon" />
                      <div className="truncate-text"> {noteTitle}</div>
                    </>
                  )}
                </div>
                {!isDraftNote(note) ? (
                  <div
                    // TODO: make testID based off of index when we add that to a NoteItem object
                    data-testid={TestID.NOTE_OPTIONS_DIV + index}
                    className={optionsId === note.id ? 'note-options selected' : 'note-options'}
                    onClick={(event) => handleNoteOptionsClick(event, note.id)}
                  >
                    <MoreHorizontal aria-hidden="true" size={15} className="context-menu-action" />
                    <span className="sr-only">Note options</span>
                  </div>
                ) : (
                  <div className="note-options">&nbsp;</div>
                )}
              </div>
              {(activeFolder === Folder.ALL || activeFolder === Folder.FAVORITES) && (
                <div className="note-category">
                  {!!noteCategory ? (
                    <>
                      <FolderIcon size={12} className="context-menu-action" />
                      {noteCategory?.name}
                    </>
                  ) : (
                    <>
                      <Book size={12} className="context-menu-action" />
                      Notes
                    </>
                  )}
                </div>
              )}
              {optionsId === note.id && !isDraftNote(note) && (
                <ContextMenu
                  contextMenuRef={contextMenuRef}
                  item={note}
                  optionsPosition={optionsPosition}
                  setOptionsId={setOptionsId}
                  type={ContextMenuEnum.NOTE}
                />
              )}
            </div>
          )
        })}
      </div>
    </aside>
  )
}

```








#### note (`src/client/slices/note.ts`)


```jsx
import { createSlice, PayloadAction } from '@reduxjs/toolkit'
import { v4 as uuid } from 'uuid'

import { Folder, NotesSortKey } from '@/utils/enums'
import { NoteItem, NoteState } from '@/types'
import { isDraftNote } from '@/utils/helpers'
import { getNotesSorter } from '@/utils/notesSortStrategies'

const getNewActiveNoteId = (
  notes: NoteItem[],
  oldNoteId: string,
  activeCategoryId: string,
  activeFolder: Folder
): string => {
  const newActiveNotes = notes
    .filter((note) => !note.scratchpad) // filter out all scratchpad notes
    .filter((note) => (activeFolder !== Folder.TRASH ? !note.trash : note.trash)) // trash or not trash
    .filter((note) => (activeCategoryId ? note.category === activeCategoryId : true)) // filter category if necessary
  const trashedNoteIndex = newActiveNotes.findIndex((note) => note.id === oldNoteId)

  if (trashedNoteIndex === 0 && newActiveNotes[1]) return newActiveNotes[1].id
  if (newActiveNotes[trashedNoteIndex - 1]) return newActiveNotes[trashedNoteIndex - 1].id

  return ''
}

export const getFirstNoteId = (
  folder: Folder,
  notes: NoteItem[],
  categoryId?: string,
  sortOrderKey?: NotesSortKey
): string => {
  const availableNotes = !sortOrderKey
    ? notes.filter((note) => !note.trash)
    : notes.filter((note) => !note.trash).sort(getNotesSorter(sortOrderKey))

  const firstNote = {
    [Folder.ALL]: () => availableNotes.find((note) => !note.scratchpad),
    [Folder.CATEGORY]: () => availableNotes.find((note) => note.category === categoryId),
    [Folder.FAVORITES]: () => availableNotes.find((note) => note.favorite),
    [Folder.SCRATCHPAD]: () => availableNotes.find((note) => note.scratchpad),
    [Folder.TRASH]: () => notes.find((note) => note.trash),
  }[folder]()

  return firstNote ? firstNote.id : ''
}

export const initialState: NoteState = {
  notes: [],
  activeCategoryId: '',
  activeFolder: Folder.ALL,
  activeNoteId: '',
  selectedNotesIds: [],
  searchValue: '',
  error: '',
  loading: true,
}

const noteSlice = createSlice({
  name: 'note',
  initialState,
  reducers: {
    addNote: (state, { payload }: PayloadAction<NoteItem>) => {
      const draftNote = state.notes.find((note) => isDraftNote(note))

      if (!draftNote) {
        state.notes.push(payload)
      }
    },

    importNotes: (state, { payload }: PayloadAction<NoteItem[]>) => {
      const toAdd = payload.map((note) => {
        note.id = uuid()

        return note
      })

      state.notes.push(...toAdd)
    },

    updateNote: (state, { payload }: PayloadAction<NoteItem>) => {
      state.notes = state.notes.map((note) =>
        note.id === payload.id
          ? { ...note, text: payload.text, lastUpdated: payload.lastUpdated }
          : note
      )
    },

    updateNotes: (
      state,
      {
        payload,
      }: PayloadAction<{
        notes: NoteItem[]
        activeFolder: Folder
        activeCategoryId?: string
        sortOrderKey?: NotesSortKey
      }>
    ) => {
      state.notes = payload.notes
      state.activeNoteId = getFirstNoteId(
        payload.activeFolder,
        payload.notes,
        payload.activeCategoryId,
        payload.sortOrderKey
      )
      state.selectedNotesIds = [
        getFirstNoteId(
          payload.activeFolder,
          payload.notes,
          payload.activeCategoryId,
          payload.sortOrderKey
        ),
      ]
    },

    deleteNotes: (state, { payload }: PayloadAction<string[]>) => {
      state.notes = state.notes.filter((note) => !payload.includes(note.id))
      state.activeNoteId = getNewActiveNoteId(
        state.notes,
        state.activeNoteId,
        state.activeCategoryId,
        state.activeFolder
      )
      state.selectedNotesIds = [
        getNewActiveNoteId(
          state.notes,
          state.activeNoteId,
          state.activeCategoryId,
          state.activeFolder
        ),
      ]
    },

    addCategoryToNote: (
      state,
      { payload }: PayloadAction<{ categoryId: string; noteId: string }>
    ) => {
      state.notes = state.selectedNotesIds.includes(payload.noteId)
        ? // Multi
          state.notes.map((note) =>
            state.selectedNotesIds.includes(note.id)
              ? { ...note, category: payload.categoryId }
              : note
          )
        : // Single
          state.notes.map((note) =>
            note.id === payload.noteId ? { ...note, category: payload.categoryId } : note
          )
    },

    removeCategoryFromNotes: (state, { payload }: PayloadAction<string>) => {
      state.notes.map((note) => {
        if (note.category === payload) {
          note.category = ''
        }
      })
    },

    updateActiveNote: (
      state,
      { payload: { noteId, multiSelect } }: PayloadAction<{ noteId: string; multiSelect: boolean }>
    ) => {
      state.activeNoteId = multiSelect
        ? state.notes.filter(({ id }) => state.selectedNotesIds.includes(id)).slice(-1)[0].id
        : noteId
    },

    updateActiveCategoryId: (state, { payload }: PayloadAction<string>) => {
      state.activeCategoryId = payload
      state.activeFolder = Folder.CATEGORY
      state.activeNoteId = getFirstNoteId(Folder.CATEGORY, state.notes, payload)
      state.selectedNotesIds = [getFirstNoteId(Folder.CATEGORY, state.notes, payload)]
      state.notes = state.notes.filter((note) => note.text !== '')
    },

    swapFolder: (
      state,
      { payload }: PayloadAction<{ folder: Folder; sortOrderKey?: NotesSortKey }>
    ) => {
      state.activeFolder = payload.folder
      state.activeCategoryId = ''
      state.activeNoteId = getFirstNoteId(
        payload.folder,
        state.notes,
        undefined,
        payload.sortOrderKey
      )
      state.selectedNotesIds = [
        getFirstNoteId(payload.folder, state.notes, undefined, payload.sortOrderKey),
      ]
      state.notes = state.notes.filter((note) => note.scratchpad || note.text !== '')
    },

    assignFavoriteToNotes: (state, { payload }: PayloadAction<string>) => {
      state.notes = state.notes.map((note) => {
        if (state.selectedNotesIds.includes(payload)) {
          return state.selectedNotesIds.includes(note.id) ? { ...note, favorite: true } : note
        }
        if (note.id === payload) {
          return { ...note, favorite: true }
        }

        return note
      })
    },

    toggleFavoriteNotes: (state, { payload }: PayloadAction<string>) => {
      state.notes = state.selectedNotesIds.includes(payload)
        ? state.notes.map((note) =>
            state.selectedNotesIds.includes(note.id) ? { ...note, favorite: !note.favorite } : note
          )
        : state.notes.map((note) =>
            note.id === payload ? { ...note, favorite: !note.favorite } : note
          )
    },

    assignTrashToNotes: (state, { payload }: PayloadAction<string>) => {
      state.notes = state.notes.map((note) => {
        if (state.selectedNotesIds.includes(payload)) {
          return state.selectedNotesIds.includes(note.id) ? { ...note, trash: true } : note
        }
        if (note.id === payload) {
          return { ...note, trash: true }
        }

        return note
      })
      state.activeNoteId = getNewActiveNoteId(
        state.notes,
        payload,
        state.activeCategoryId,
        state.activeFolder
      )
      state.selectedNotesIds = [
        getNewActiveNoteId(state.notes, payload, state.activeCategoryId, state.activeFolder),
      ]
    },

    toggleTrashNotes: (state, { payload }: PayloadAction<string>) => {
      state.notes = state.selectedNotesIds.includes(payload)
        ? state.notes.map((note) =>
            state.selectedNotesIds.includes(note.id) ? { ...note, trash: !note.trash } : note
          )
        : state.notes.map((note) => (note.id === payload ? { ...note, trash: !note.trash } : note))
      state.activeNoteId = getNewActiveNoteId(
        state.notes,
        payload,
        state.activeCategoryId,
        state.activeFolder
      )
      state.selectedNotesIds = [
        getNewActiveNoteId(state.notes, payload, state.activeCategoryId, state.activeFolder),
      ]
    },

    unassignTrashFromNotes: (state, { payload }: PayloadAction<string>) => {
      state.notes = state.notes.map((note) => {
        if (state.selectedNotesIds.includes(payload)) {
          return state.selectedNotesIds.includes(note.id) && note.trash
            ? { ...note, trash: false }
            : note
        }
        if (note.id === payload) {
          return { ...note, trash: false }
        }

        return note
      })
    },

    updateSelectedNotes: (
      state,
      { payload: { noteId, multiSelect } }: PayloadAction<{ noteId: string; multiSelect: boolean }>
    ) => {
      state.selectedNotesIds = multiSelect
        ? state.selectedNotesIds.length === 1 && state.selectedNotesIds[0] === noteId
          ? state.selectedNotesIds
          : state.selectedNotesIds.includes(noteId)
          ? state.selectedNotesIds.filter((selectedNoteId) => selectedNoteId !== noteId)
          : [...state.selectedNotesIds, noteId]
        : [noteId]
    },

    permanentlyEmptyTrash: (state) => {
      state.notes = state.notes.filter((note) => !note.trash)
    },

    pruneNotes: (state) => {
      state.notes = state.notes.filter(
        (note) => note.scratchpad || note.text !== '' || state.selectedNotesIds.includes(note.id)
      )
    },

    searchNotes: (state, { payload }: PayloadAction<string>) => {
      state.searchValue = payload
    },

    loadNotes: (state) => {
      state.loading = true
    },

    loadNotesError: (state, { payload }: PayloadAction<string>) => {
      state.loading = false
      state.error = payload
    },

    loadNotesSuccess: (
      state,
      { payload }: PayloadAction<{ notes: NoteItem[]; sortOrderKey?: NotesSortKey }>
    ) => {
      state.notes = payload.notes
      state.activeNoteId = getFirstNoteId(
        Folder.ALL,
        payload.notes,
        undefined,
        payload.sortOrderKey
      )
      state.selectedNotesIds = [
        getFirstNoteId(Folder.ALL, payload.notes, undefined, payload.sortOrderKey),
      ]
      state.loading = false
    },
  },
})

export const {
  addNote,
  updateNote,
  updateNotes,
  deleteNotes,
  addCategoryToNote,
  removeCategoryFromNotes,
  updateActiveNote,
  updateActiveCategoryId,
  swapFolder,
  assignFavoriteToNotes,
  toggleFavoriteNotes,
  assignTrashToNotes,
  toggleTrashNotes,
  unassignTrashFromNotes,
  updateSelectedNotes,
  permanentlyEmptyTrash,
  pruneNotes,
  searchNotes,
  loadNotes,
  loadNotesError,
  loadNotesSuccess,
  importNotes,
} = noteSlice.actions

export default noteSlice.reducer

